INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3891434, 552836, 47316, '<td valign="top">Beautiful! Wish you could see more of her expression. The concept and colors, everything very nice!</td>', 'Beautiful! Wish you could see more of her expression. The concept and colors, everything very nice!', '2007-07-11 01:06:45.000000', NULL, 1),
(3891440, 552742, 47316, '<td valign="top">not a can of the processing here with it so bright right on her face. I realize you were going for a dreamy effect but I find it over the top. THe shot is beautiful as well as your model.</td>', 'not a can of the processing here with it so bright right on her face. I realize you were going for a dreamy effect but I find it over the top. THe shot is beautiful as well as your model.', '2007-07-11 01:08:03.000000', NULL, 1),
(3891449, 552681, 47316, '<td valign="top">eerie. love the expression, or lack there of. good choice on going b/w.</td>', 'eerie. love the expression, or lack there of. good choice on going b/w.', '2007-07-11 01:09:09.000000', NULL, 1),
(3891453, 552007, 35669, '<td valign="top">i guess team spleen cought public transport this week!   :)</td>', 'i guess team spleen cought public transport this week!   :)', '2007-07-11 01:09:38.000000', NULL, 1),
(3891457, 550391, 15711, '<td valign="top">I love the silhouette with the lace curtains.</td>', 'I love the silhouette with the lace curtains.', '2007-07-11 01:10:20.000000', NULL, 1),
(3891458, 551234, 47316, '<td valign="top">nice shot! how cool to see that!</td>', 'nice shot! how cool to see that!', '2007-07-11 01:10:27.000000', NULL, 1),
(3891463, 550046, 15711, '<td valign="top">This definitely has more possibilities as a dream than most I''ve seen. I love all of their various positions. I''m a huge fan of silhouettes (hee hee - my entry has one too).</td>', 'This definitely has more possibilities as a dream than most I''ve seen. I love all of their various positions. I''m a huge fan of silhouettes (hee hee - my entry has one too).', '2007-07-11 01:11:07.000000', NULL, 1),
(3891466, 552776, 47316, '<td valign="top">cute. not your typical models but the expression look very genuine and that wins for me. like the color of the water... kind of silver. I think you went a bit out on a limb with the title, I would have kept it more on the couple.</td>', 'cute. not your typical models but the expression look very genuine and that wins for me. like the color of the water... kind of silver. I think you went a bit out on a limb with the title, I would have kept it more on the couple.', '2007-07-11 01:12:12.000000', NULL, 1),
(3891476, 551182, 15711, '<td valign="top">I like the dude in the background with the scrunched up face, trying to figure out how to work his camera. ROFL</td>', 'I like the dude in the background with the scrunched up face, trying to figure out how to work his camera. ROFL', '2007-07-11 01:13:41.000000', NULL, 1),
(3891482, 552761, 15711, '<td valign="top">One of the few that has a possible dream connection.</td>', 'One of the few that has a possible dream connection.', '2007-07-11 01:14:16.000000', NULL, 1),
(3891483, 552679, 15711, '<td valign="top">I tried to capture a jack rabbit the other day and man are those buggers fast.  I like the backlighting through his ears.</td>', 'I tried to capture a jack rabbit the other day and man are those buggers fast.  I like the backlighting through his ears.', '2007-07-11 01:14:53.000000', NULL, 1),
