(3891508, 552977, 47316, '<td valign="top">aww very pretty!</td>', 'aww very pretty!', '2007-07-11 01:19:01.000000', NULL, 1),
(3891510, 552836, 15711, '<td valign="top">How fun.  One of the few imaginative actual "a dream you''ve had" type images.  I love the balloons. Great use of negative space. That touch of green is great. 7</td>', 'How fun.  One of the few imaginative actual "a dream you''ve had" type images.  I love the balloons. Great use of negative space. That touch of green is great. 7', '2007-07-11 01:19:15.000000', NULL, 1),
(3891513, 550671, 47316, '<td valign="top">this is really neat!</td>', 'this is really neat!', '2007-07-11 01:19:48.000000', NULL, 1),
(3891520, 552777, 15711, '<td valign="top">I love this.  Great composition and the horse looked at you at the perfect time.</td>', 'I love this.  Great composition and the horse looked at you at the perfect time.', '2007-07-11 01:21:21.000000', NULL, 1),
(3891541, 549055, 66709, '<td valign="top">nice concept and well done</td>', 'nice concept and well done', '2007-07-11 01:25:03.000000', NULL, 1),
(3891565, 552742, 61818, '<td valign="top">Think the high key effect is a little over the top.  Just a tad, but its my opinion.  Otherwise a lovely shot and what a gorgeous model.</td>', 'Think the high key effect is a little over the top.  Just a tad, but its my opinion.  Otherwise a lovely shot and what a gorgeous model.', '2007-07-11 01:30:55.000000', NULL, 1),
