(3900929, 550391, 42254, '<td valign="top">The soft blue light creates a dream-like effect--nice job.</td>', 'The soft blue light creates a dream-like effect--nice job.', '2007-07-13 16:01:36.000000', NULL, 1),
(3900934, 552555, 42254, '<td valign="top">I agree, but this one is out of focus.</td>', 'I agree, but this one is out of focus.', '2007-07-13 16:02:28.000000', NULL, 1),
(3900947, 549885, 42254, '<td valign="top">Beautiful contrast of deep green grass in foreground with the blue-greens of the mountains, and then the blue sky...leads the eye heavenward.  The couple may be a distraction, but could be focused on more by cropping closer to them. Especially if you mean to suggest that they are the dreamers.</td>', 'Beautiful contrast of deep green grass in foreground with the blue-greens of the mountains, and then the blue sky...leads the eye heavenward.  The couple may be a distraction, but could be focused on more by cropping closer to them. Especially if you mean to suggest that they are the dreamers.', '2007-07-13 16:06:36.000000', NULL, 1),
(3900955, 550119, 42254, '<td valign="top">Beautiful waterfall &amp; pool.  I think I''d crop out the blurred water in the forground--it seems to distract.  Still worth a 7.</td>', 'Beautiful waterfall & pool.  I think I''d crop out the blurred water in the forground--it seems to distract.  Still worth a 7.', '2007-07-13 16:08:08.000000', NULL, 1),
(3900962, 551685, 42254, '<td valign="top">Wow! What a sky!  Great shot--especially to include the silhouette of the dreamer.</td>', 'Wow! What a sky!  Great shot--especially to include the silhouette of the dreamer.', '2007-07-13 16:12:00.000000', NULL, 1),
(3900968, 551115, 42254, '<td valign="top">Neat photo--great color, interest, eyes, sharpness of foreground with blurred background.  The only suggestion might be to crop out the shutter frame on the left; it doesn''t add anything to the shot and may distract from the subject.</td>', 'Neat photo--great color, interest, eyes, sharpness of foreground with blurred background.  The only suggestion might be to crop out the shutter frame on the left; it doesn''t add anything to the shot and may distract from the subject.', '2007-07-13 16:14:11.000000', NULL, 1),
(3900971, 552975, 42254, '<td valign="top">This is so unusual that it''s hard to rate! I can''t figure how you did it, but it is such a clean shot &amp; so suggestive of the challenge category, that I''m impressed. The more I view it, the higher my rating goes--I''d better stop!</td>', 'This is so unusual that it''s hard to rate! I can''t figure how you did it, but it is such a clean shot & so suggestive of the challenge category, that I''m impressed. The more I view it, the higher my rating goes--I''d better stop!', '2007-07-13 16:17:23.000000', NULL, 1),
(3900972, 552653, 42254, '<td valign="top">I wonder if a little too blurred to make your other world point?  Lovely colors, however.</td>', 'I wonder if a little too blurred to make your other world point?  Lovely colors, however.', '2007-07-13 16:18:16.000000', NULL, 1),
(3900976, 550342, 42254, '<td valign="top">Interesting--IR gives a dream-like aura to this shot.  Nice job.</td>', 'Interesting--IR gives a dream-like aura to this shot.  Nice job.', '2007-07-13 16:20:22.000000', NULL, 1),
(3900980, 552685, 42254, '<td valign="top">Impressive! You can picture him dreaming.</td>', 'Impressive! You can picture him dreaming.', '2007-07-13 16:22:03.000000', NULL, 1),
