(3903465, 551945, 76430, '<td valign="top">I think this is a duck, but it''s hard to tell by the shape in the silouette.  I''m trying to figure out the title meaning.  Outside of that I like the water reflections and waves a lot.</td>', 'I think this is a duck, but it''s hard to tell by the shape in the silouette.  I''m trying to figure out the title meaning.  Outside of that I like the water reflections and waves a lot.', '2007-07-14 17:12:56.000000', NULL, 1),
(3903476, 551276, 76430, '<td valign="top">Nice dreamy look with the long exposure.  Nice color combination.</td>', 'Nice dreamy look with the long exposure.  Nice color combination.', '2007-07-14 17:17:27.000000', NULL, 1),
(3903483, 551031, 76430, '<td valign="top">I''m sure you''ve heard this many times already, but the harsh lighting and shadows from the on-camera flash really washes this out.  Without the flash, using lamps, etc, would have made this much better.  Good detail.</td>', 'I''m sure you''ve heard this many times already, but the harsh lighting and shadows from the on-camera flash really washes this out.  Without the flash, using lamps, etc, would have made this much better.  Good detail.', '2007-07-14 17:19:35.000000', NULL, 1),
(3903508, 551298, 76430, '<td valign="top">Usually long titles help clarify the image, but this one is confusing to me.  I like the clouds and sun rays.</td>', 'Usually long titles help clarify the image, but this one is confusing to me.  I like the clouds and sun rays.', '2007-07-14 17:27:50.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3903514, 552902, 76430, '<td valign="top">Nice picture with fir tree foreground, lush valley, and mountain floating over the haze.</td>', 'Nice picture with fir tree foreground, lush valley, and mountain floating over the haze.', '2007-07-14 17:30:13.000000', NULL, 1),
(3903521, 549055, 76430, '<td valign="top">Creative picture.  The lens flare is unfortunate, but it does sort of go with the theme.</td>', 'Creative picture.  The lens flare is unfortunate, but it does sort of go with the theme.', '2007-07-14 17:34:02.000000', NULL, 1),
(3903523, 552681, 76430, '<td valign="top">Good DOF and B/W.  Nice dreamy expression on the child.  Some Neat Image would help here IMHO.</td>', 'Good DOF and B/W.  Nice dreamy expression on the child.  Some Neat Image would help here IMHO.', '2007-07-14 17:37:26.000000', NULL, 1),
(3903525, 552682, 76430, '<td valign="top">Extra points for creativity, but losing some for technical merit.  It needs more sharpness and maybe some saturation to make it pop.</td>', 'Extra points for creativity, but losing some for technical merit.  It needs more sharpness and maybe some saturation to make it pop.', '2007-07-14 17:39:09.000000', NULL, 1),
(3903530, 552766, 76430, '<td valign="top">Nice upside down image of a reflection really makes this picture.  Meets the challenge well.  9</td>', 'Nice upside down image of a reflection really makes this picture.  Meets the challenge well.  9', '2007-07-14 17:42:38.000000', NULL, 1),
(3903540, 550401, 76430, '<td valign="top">Very nice soft image.  Brightness of the deer makes it look like a vision.  9</td>', 'Very nice soft image.  Brightness of the deer makes it look like a vision.  9', '2007-07-14 17:49:42.000000', NULL, 1),
(3903554, 552685, 76430, '<td valign="top">Beautiful picture.  Good exposure, composition, thirds placement, meeting challenge.  8</td>', 'Beautiful picture.  Good exposure, composition, thirds placement, meeting challenge.  8', '2007-07-14 18:11:19.000000', NULL, 1),
(3903565, 552872, 76430, '<td valign="top">Nice flower macro with sharp center and soft petals.  Are the colors modified to bring out the strong blue?</td>', 'Nice flower macro with sharp center and soft petals.  Are the colors modified to bring out the strong blue?', '2007-07-14 18:20:43.000000', NULL, 1),
(3903577, 552587, 76430, '<td valign="top">The title works on multiple levels here with the guy observing/admiring himself, the sign with beauties, and the MegaMax store (whatever that is). The Netherlands?</td>', 'The title works on multiple levels here with the guy observing/admiring himself, the sign with beauties, and the MegaMax store (whatever that is). The Netherlands?', '2007-07-14 18:29:43.000000', NULL, 1),
