(3908678, 552668, 67697, '<td valign="top">Wow this looks like an ad you''d find in a rock magazine.  I really hope you have written down where this took place because I''d love to know what was going on when you took this.</td>', 'Wow this looks like an ad you''d find in a rock magazine.  I really hope you have written down where this took place because I''d love to know what was going on when you took this.', '2007-07-16 17:50:34.000000', NULL, 1),
(3908682, 551853, 67697, '<td valign="top">I''m not really able to relate the title to the pic.  But the pic is very pretty.  Love the sky and the silhouette.</td>', 'I''m not really able to relate the title to the pic.  But the pic is very pretty.  Love the sky and the silhouette.', '2007-07-16 17:51:19.000000', NULL, 1),
(3908684, 552440, 67697, '<td valign="top">Very striking photo.  The fact that she is wearing such a bright red lipstick is a great contrast to all the peacock feathers.</td>', 'Very striking photo.  The fact that she is wearing such a bright red lipstick is a great contrast to all the peacock feathers.', '2007-07-16 17:51:57.000000', NULL, 1),
(3908689, 551579, 67697, '<td valign="top">I don''t really understand the dreams portion of this but I do love the picture.  Great black and white and the comparison of the person in front with the reflection of the younger person is just excellent.</td>', 'I don''t really understand the dreams portion of this but I do love the picture.  Great black and white and the comparison of the person in front with the reflection of the younger person is just excellent.', '2007-07-16 17:53:10.000000', NULL, 1),
