INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3910673, 552975, 67616, '<td valign="top">Interesting use of a frequently photographed structure.</td>', 'Interesting use of a frequently photographed structure.', '2007-07-17 14:21:31.000000', NULL, 1),
(3910675, 550697, 67616, '<td valign="top">Very graphic</td>', 'Very graphic', '2007-07-17 14:22:56.000000', NULL, 1),
(3910703, 551619, 77176, '<td valign="top">I don''t get it.</td>', 'I don''t get it.', '2007-07-17 14:34:15.000000', NULL, 1),
(3910813, 551912, 81329, '<td valign="top">Nice silhouette.  The reflections off the water are a little distracting.  I slower shutter speed probably would have helped.</td>', 'Nice silhouette.  The reflections off the water are a little distracting.  I slower shutter speed probably would have helped.', '2007-07-17 15:12:36.000000', NULL, 1),
(3910815, 552238, 81329, '<td valign="top">Nice shot of the flag!  It''s very clear, and well-composed.</td>', 'Nice shot of the flag!  It''s very clear, and well-composed.', '2007-07-17 15:13:07.000000', NULL, 1),
(3910818, 552087, 81329, '<td valign="top">There''s just too much empty space, and not enough to really catch your eye.</td>', 'There''s just too much empty space, and not enough to really catch your eye.', '2007-07-17 15:13:41.000000', NULL, 1),
(3910822, 552102, 81329, '<td valign="top">The other flag photo in this contest is better.  The lighting is a little dark in this one.</td>', 'The other flag photo in this contest is better.  The lighting is a little dark in this one.', '2007-07-17 15:14:41.000000', NULL, 1),
(3910825, 552755, 81329, '<td valign="top">There''s just too much dirt.  Try to follow the rule of thirds in your compositions.</td>', 'There''s just too much dirt.  Try to follow the rule of thirds in your compositions.', '2007-07-17 15:15:30.000000', NULL, 1),
(3910829, 551820, 81329, '<td valign="top">Cute cat, and nice angle and composition.  The colors are sharp, but the lighting could be a little better.</td>', 'Cute cat, and nice angle and composition.  The colors are sharp, but the lighting could be a little better.', '2007-07-17 15:16:21.000000', NULL, 1),
(3910900, 551824, 81390, '<td valign="top">Ooh, lovely. The wings are blurred just enough to make it dreamlike, and it works having its head peering out as if it''s beckoning you to follow.</td>', 'Ooh, lovely. The wings are blurred just enough to make it dreamlike, and it works having its head peering out as if it''s beckoning you to follow.', '2007-07-17 15:47:00.000000', NULL, 1),
(3910906, 552216, 81390, '<td valign="top">An eye-catching photo with a very complementary title. I love the framing, and that seeing it full size with all the details is rewarding. Seems like it was over-compressed, though, and that white dot to the right of the branch is unfortunate.</td>', 'An eye-catching photo with a very complementary title. I love the framing, and that seeing it full size with all the details is rewarding. Seems like it was over-compressed, though, and that white dot to the right of the branch is unfortunate.', '2007-07-17 15:48:51.000000', NULL, 1),
(3910944, 552312, 31637, '<td valign="top">Zeta Reticuli?</td>', 'Zeta Reticuli?', '2007-07-17 16:16:07.000000', NULL, 1),
(3910945, 552731, 31637, '<td valign="top">10 all the way, this is a masterpiece.</td>', '10 all the way, this is a masterpiece.', '2007-07-17 16:17:01.000000', NULL, 1),
